#!/usr/bin/env python3
import sys, os, re, json, shutil, zipfile

INPUT_DOCX = "inputs/offer_letter_template.docx"
DATA_JSON  = "inputs/employee_data.json"
OUTPUT_DOCX = "output/offer_letter_filled.docx"

def fail(msg):
    sys.stderr.write("ERROR: " + msg + "\n")
    sys.exit(2)

with open(DATA_JSON, encoding="utf-8") as f:
    data = json.load(f)

# Parts of the docx that may contain placeholders / active headers+footers.
PART_RE = re.compile(r'^word/(document|header\d+|footer\d+)\.xml$')

COND_GOVERNOR = "RELOCATION_PACKAGE"   # the ONLY governing field
KEEP_VALUE = "Yes"                     # exact-string match keeps content

# Regex to iterate paragraphs (process per-paragraph so tokens never cross paragraphs)
PARA_RE = re.compile(r'<w:p(?:\s[^>]*)?>.*?</w:p>', re.S)
WT_RE   = re.compile(r'(<w:t(?:\s[^>]*)?>)(.*?)(</w:t>)', re.S)
TOKEN_RE = re.compile(r'\{\{([A-Z_]+)\}\}')

missing = []  # (field, where)

def resolve_field(name, where):
    if name in data and str(data[name]) != "":
        return str(data[name])
    missing.append((name, where))
    return None

def process_text(full_text, where):
    """Replace placeholders and apply conditional on the concatenated paragraph text."""
    # Handle conditional block(s): {{IF_RELOCATION}} ... {{END_IF_RELOCATION}}
    cond_re = re.compile(r'\{\{IF_RELOCATION\}\}(.*?)\{\{END_IF_RELOCATION\}\}', re.S)
    def cond_sub(m):
        # governor is REQUIRED whenever the conditional appears
        gov = resolve_field(COND_GOVERNOR, where + " (conditional governor)")
        inner = m.group(1)
        if gov is None:
            return inner  # placeholder; run will fail later anyway
        if gov == KEEP_VALUE:
            return inner   # exact "Yes" -> keep inner content
        return ""          # every other string -> remove
    full_text = cond_re.sub(cond_sub, full_text)

    # Any leftover IF/END markers (unbalanced) are an error-worthy condition
    if 'IF_RELOCATION' in full_text or 'END_IF_RELOCATION' in full_text:
        # treat as unresolved; but tokens are {{...}} so catch below
        pass

    # Replace remaining simple placeholders
    def tok_sub(m):
        name = m.group(1)
        if name in ("IF_RELOCATION", "END_IF_RELOCATION"):
            return m.group(0)  # should be gone; leave for detection
        val = resolve_field(name, where)
        return val if val is not None else m.group(0)
    full_text = TOKEN_RE.sub(tok_sub, full_text)
    return full_text

def process_paragraph(para, where):
    runs = list(WT_RE.finditer(para))
    if not runs:
        return para
    concatenated = "".join(m.group(2) for m in runs)
    if "{{" not in concatenated:
        return para
    new_text = process_text(concatenated, where)
    # Put all resulting text into the first w:t run; empty the rest.
    out = []
    last = 0
    for idx, m in enumerate(runs):
        out.append(para[last:m.start()])
        if idx == 0:
            out.append(m.group(1) + new_text + m.group(3))
        else:
            out.append(m.group(1) + m.group(3))
        last = m.end()
    out.append(para[last:])
    return "".join(out)

def process_part(xml, where):
    return PARA_RE.sub(lambda m: process_paragraph(m.group(0), where), xml)

# Read, transform, write
os.makedirs(os.path.dirname(OUTPUT_DOCX), exist_ok=True)
zin = zipfile.ZipFile(INPUT_DOCX, "r")
items = []
for info in zin.infolist():
    raw = zin.read(info.filename)
    if PART_RE.match(info.filename):
        xml = raw.decode("utf-8")
        xml = process_part(xml, info.filename)
        raw = xml.encode("utf-8")
    items.append((info, raw))
zin.close()

if missing:
    # dedupe preserving order
    seen = set(); uniq = []
    for name, where in missing:
        key = (name, where)
        if key not in seen:
            seen.add(key); uniq.append((name, where))
    for name, where in uniq:
        sys.stderr.write(f"MISSING REQUIRED: {name} in {where}\n")
    fail(f"{len(uniq)} required value(s) missing; aborting without writing output.")

# Escape check: ensure no unresolved placeholders remain
for info, raw in items:
    if PART_RE.match(info.filename):
        t = raw.decode("utf-8")
        leftover = set(TOKEN_RE.findall(t))
        if leftover:
            fail(f"Unresolved placeholders in {info.filename}: {sorted(leftover)}")

zout = zipfile.ZipFile(OUTPUT_DOCX, "w", zipfile.ZIP_DEFLATED)
for info, raw in items:
    zout.writestr(info, raw)
zout.close()

print("Wrote", OUTPUT_DOCX)
